fn toggle_case(s: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    
    for ch in s {
        if ch.is_ascii_lowercase() {
            result.push(ch.to_ascii_uppercase());
        } else if ch.is_ascii_uppercase() {
            result.push(ch.to_ascii_lowercase());
        } else {
            result.push(ch);
        }
    }
    
    result
}